package com.loja.checkout.enum;

public enum ModalidadeEntrega {
    ECONOMICA("ECONOMICA"),
    EXPRESSA("EXPRESSA"),
    RETIRADA_LOJA("RETIRADA_LOJA"),
    MOTOBOY("MOTOBOY");

    private final String codigo;

    ModalidadeEntrega(String codigo) {
        this.codigo = codigo;
    }

    public static ModalidadeEntrega de(String codigo) {
        for (ModalidadeEntrega m : values()) {
            if (m.codigo.equals(codigo)) {
                return m;
            }
        }
        return null;
    }
}

package com.loja.checkout.estrategia;

import com.loja.checkout.enum.ModalidadeEntrega;

public class FabricaEntrega {
    public static EstrategiaEntrega criar(ModalidadeEntrega modalidade) {
        return switch (modalidade) {
            case ECONOMICA -> new EntregaEconomica();
            case EXPRESSA -> new EntregaExpressa();
            case RETIRADA_LOJA -> new EntregaRetiradaLoja();
            case MOTOBOY -> new EntregaMotoboy();
        };
    }
}

package com.loja.checkout.estrategia;

import com.loja.checkout.enum.Cupom;

public class FabricaCupom {
    public static EstrategiaCupom criar(Cupom cupom) {
        if (cupom == null) {
            return new CupomNenhum();
        }
        return switch (cupom) {
            case BEMVINDO10 -> new CupomBemvindo10();
            case MENOS50 -> new CupomMenos50();
            case FRETEGRATIS -> new CupomFreteGratis();
            case LEVE3PAGUE2 -> new CupomLeve3Pague2();
        };
    }
}

package com.loja.checkout.estrategia;

import com.loja.checkout.enum.FormaPagamento;

public class FabricaFormaPagamento {
    public static EstrategiaFormaPagamento criar(FormaPagamento forma) {
        return switch (forma) {
            case PIX -> new PagamentoPix();
            case CARTAO -> new PagamentoCartao();
            case BOLETO -> new PagamentoBoleto();
        };
    }
}

package com.loja.checkout.estrategia;

import com.loja.checkout.enum.NivelClube;

public class FabricaClube {
    public static EstrategiaClube criar(NivelClube nivel) {
        return switch (nivel) {
            case BRONZE -> new ClubeNivelBronze();
            case PRATA -> new ClubeNivelPrata();
            case OURO -> new ClubeNivelOuro();
        };
    }
}

