            if (item.precoUnitario() <= 0 || item.quantidade() <= 0 || item.pesoKg() <= 0) {
                throw new ErroCheckout("PEDIDO_INVALIDO");
            }
        }
    }

    private void validarNivelClubeExiste(NivelClube nivelClube) throws ErroCheckout {
        if (nivelClube == null) {
