1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.dto.ItemRequest;
4	import com.loja.checkout.dto.ResumoRequest;
5	import com.loja.checkout.dto.ResumoResponse;
6	import com.loja.checkout.domain.*;
7	import com.loja.checkout.exception.ErroCheckout;
8	import com.loja.checkout.estrategia.*;
9	import com.loja.checkout.util.Arredondamento;
10	import org.springframework.stereotype.Service;
11	
12	import java.util.List;
13	
14	@Service
15	public class ResumoCompraService {
16	
17	    public ResumoResponse calcular(ResumoRequest request) throws ErroCheckout {
18	        validarPedido(request);
19	
20	        List<ItemRequest> itens = request.itens();
21	        double subtotalProdutos = calcularSubtotal(itens);
22	
23	        NivelClube nivelClube = NivelClube.de(request.nivelClube());
24	        Regiao regiao = Regiao.de(request.regiao());
25	        ModalidadeEntrega modalidade = ModalidadeEntrega.de(request.modalidadeEntrega());
26	        Cupom cupom = Cupom.de(request.cupom());
27	        FormaPagamento formaPagamento = FormaPagamento.de(request.formaPagamento());
28	
29	        validarModalidadeExiste(modalidade);
30	        validarNivelClubeExiste(nivelClube);
31	        validarRegiaoExiste(regiao);
32	        validarCupomExiste(cupom, request.cupom());
33	        validarFormaPagamentoExiste(formaPagamento);
34	
35	        EstrategiaClube estrategiaClube = FabricaClube.criar(nivelClube);
36	        EstrategiaEntrega estrategiaEntrega = FabricaEntrega.criar(modalidade);
37	        EstrategiaCupom estrategiaCupom = FabricaCupom.criar(cupom);
38	        EstrategiaFormaPagamento estrategiaFormaPagamento = FabricaFormaPagamento.criar(formaPagamento);
39	
40	        validarModalidadeDisponivel(estrategiaEntrega, itens);
41	        validarCupomAplicavel(estrategiaCupom, subtotalProdutos, itens, cupom);
42	
43	        double pesoTotal = calcularPesoTotal(itens);
44	
45	        double descontoCupom = estrategiaCupom.calcularDesconto(subtotalProdutos, itens);
46	        double frete = estrategiaEntrega.calcularFrete(pesoTotal);
47	
48	        if (estrategiaClube.ehIsento(request.modalidadeEntrega())) {
49	            frete = 0.0;
50	        }
51	
52	        frete = estrategiaCupom.ajustarFretePorCupom(frete);
53	
54	        double seguro = calcularSeguro(subtotalProdutos, regiao);
55	        int prazoEntregaDias = estrategiaEntrega.prazoEntregaDias();
56	
57	        double totalPedido = Arredondamento.arredondar(subtotalProdutos - descontoCupom + frete + seguro);
58	
59	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
60	        validarParcelamento(formaPagamento, parcelas, totalPedido);
61	        validarFormaPagamentoDisponivel(formaPagamento, totalPedido);
62	
63	        double ajustePagamento = estrategiaFormaPagamento.calcularAjuste(totalPedido, parcelas);
64	        double totalFinal = Arredondamento.arredondar(totalPedido + ajustePagamento);
65	
66	        int parcelasNoResponse = estrategiaFormaPagamento.getParcelasNoResponse(parcelas);
67	        double valorParcela = estrategiaFormaPagamento.getValorParcela(totalFinal, parcelasNoResponse);
68	
69	        double creditoProximaCompra = estrategiaClube.calcularCredito(subtotalProdutos);
70	        boolean temBrinde = estrategiaClube.temBrinde(subtotalProdutos);
71	
72	        return new ResumoResponse(
73	            subtotalProdutos,
74	            descontoCupom,
75	            frete,
76	            prazoEntregaDias,
77	            seguro,
78	            ajustePagamento,
79	            totalFinal,
80	            parcelasNoResponse,
81	            valorParcela,
82	            creditoProximaCompra,
83	            temBrinde
84	        );
85	    }
86	
87	    private void validarPedido(ResumoRequest request) throws ErroCheckout {
88	        if (request.itens() == null || request.itens().isEmpty()) {
89	            throw new ErroCheckout("PEDIDO_INVALIDO");
90	        }
91	
92	        for (ItemRequest item : request.itens()) {
93	            if (item.precoUnitario() <= 0 || item.quantidade() <= 0 || item.pesoKg() <= 0) {
94	                throw new ErroCheckout("PEDIDO_INVALIDO");
95	            }
96	        }
97	    }
98	
99	    private void validarNivelClubeExiste(NivelClube nivelClube) throws ErroCheckout {
100	        if (nivelClube == null) {
101	            throw new ErroCheckout("NIVEL_CLUBE_INVALIDO");
102	        }
103	    }
104	
105	    private void validarRegiaoExiste(Regiao regiao) throws ErroCheckout {
106	        if (regiao == null) {
107	            throw new ErroCheckout("REGIAO_INVALIDA");
108	        }
109	    }
110	
111	    private void validarModalidadeExiste(ModalidadeEntrega modalidade) throws ErroCheckout {
112	        if (modalidade == null) {
113	            throw new ErroCheckout("MODALIDADE_INVALIDA");
114	        }
115	    }
116	
117	    private void validarCupomExiste(Cupom cupom, String cupomOriginal) throws ErroCheckout {
118	        if (cupomOriginal != null && cupom == null) {
119	            throw new ErroCheckout("CUPOM_INVALIDO");
120	        }
121	    }
122	
123	    private void validarFormaPagamentoExiste(FormaPagamento formaPagamento) throws ErroCheckout {
124	        if (formaPagamento == null) {
125	            throw new ErroCheckout("FORMA_PAGAMENTO_INVALIDA");
126	        }
127	    }
128	
129	    private void validarModalidadeDisponivel(EstrategiaEntrega estrategia, List<ItemRequest> itens) throws ErroCheckout {
130	        double pesoTotal = calcularPesoTotal(itens);
131	        if (!estrategia.disponivel(pesoTotal)) {
132	            throw new ErroCheckout("MODALIDADE_INDISPONIVEL");
133	        }
134	    }
135	
136	    private void validarCupomAplicavel(EstrategiaCupom estrategia, double subtotal, List<ItemRequest> itens, Cupom cupom) throws ErroCheckout {
137	        if (cupom == null) {
138	            return;
139	        }
140	        if (!estrategia.aplicavel(subtotal, itens)) {
141	            throw new ErroCheckout("CUPOM_NAO_APLICAVEL");
142	        }
143	    }
144	
145	    private void validarParcelamento(FormaPagamento forma, int parcelas, double total) throws ErroCheckout {
146	        if (forma == FormaPagamento.PIX || forma == FormaPagamento.BOLETO) {
147	            if (parcelas != 1) {
148	                throw new ErroCheckout("PARCELAMENTO_INVALIDO");
149	            }
150	        } else if (forma == FormaPagamento.CARTAO) {
151	            if (parcelas < 1 || parcelas > 12) {
152	                throw new ErroCheckout("PARCELAMENTO_INVALIDO");
153	            }
154	        }
155	    }
156	
157	    private void validarFormaPagamentoDisponivel(FormaPagamento forma, double total) throws ErroCheckout {
158	        if (forma == FormaPagamento.BOLETO && total > 1000.00) {
159	            throw new ErroCheckout("FORMA_PAGAMENTO_INDISPONIVEL");
160	        }
161	    }
162	
163	    private double calcularSubtotal(List<ItemRequest> itens) {
164	        double subtotal = 0.0;
165	        for (ItemRequest item : itens) {
166	            subtotal += item.precoUnitario() * item.quantidade();
167	        }
168	        return Arredondamento.arredondar(subtotal);
169	    }
170	
171	    private double calcularPesoTotal(List<ItemRequest> itens) {
172	        double peso = 0.0;
173	        for (ItemRequest item : itens) {
174	            peso += item.pesoKg() * item.quantidade();
175	        }
176	        return peso;
177	    }
178	
179	    private double calcularSeguro(double subtotalProdutos, Regiao regiao) {
180	        double percentual = switch (regiao) {
181	            case SUDESTE, SUL -> 0.01;
182	            case CENTRO_OESTE -> 0.015;
183	            case NORTE -> 0.025;
184	            case NORDESTE -> 0.02;
185	        };
186	        return Arredondamento.arredondar(subtotalProdutos * percentual);
187	    }
188	}
