5	public class PagamentoCartao implements EstrategiaFormaPagamento {
6	    private double totalPedidoArmazenado = 0.0;
7	
8	    @Override
9	    public double calcularAjuste(double total, int parcelas) {
10	        totalPedidoArmazenado = total;
11	
12	        if (parcelas <= 3) {
13	            return 0.0;
14	        }
15	
16	        double taxaMensal = 0.0199;
17	        double numerador = total * taxaMensal;
18	        double denominador = 1.0 - Math.pow(1.0 + taxaMensal, -parcelas);
19	        double parcelaComJuros = numerador / denominador;
20	        parcelaComJuros = Arredondamento.arredondar(parcelaComJuros);
21	        double totalComJuros = Arredondamento.arredondar(parcelaComJuros * parcelas);
22	        double ajuste = totalComJuros - total;
23	
24	        return Arredondamento.arredondar(ajuste);
25	    }
26	
27	    @Override
28	    public int getParcelasNoResponse(int parcelasRequisitadas) {
29	        return parcelasRequisitadas;
30	    }
31	
32	    @Override
33	    public double getValorParcela(double total, int parcelas) {
34	        if (parcelas <= 3) {
35	            return Arredondamento.arredondar(total / parcelas);
36	        }
37	
38	        double taxaMensal = 0.0199;
39	        double numerador = totalPedidoArmazenado * taxaMensal;
40	        double denominador = 1.0 - Math.pow(1.0 + taxaMensal, -parcelas);
41	        double parcelaComJuros = numerador / denominador;
42	        return Arredondamento.arredondar(parcelaComJuros);
43	    }
