public class CupomFreteGratis implements EstrategiaCupom {
    private double freteAtualizacaoPrevista = 0.0;

    @Override
    public double calcularDesconto(double subtotalProdutos, List<ItemRequest> itens) {
        return Arredondamento.arredondar(freteAtualizacaoPrevista);
    }

    @Override
    public boolean aplicavel(double subtotalProdutos, List<ItemRequest> itens) {
        return true;
    }

    @Override
